-- ============================================================
-- Mapa único del campus UCC Santa Marta
-- ============================================================
-- Un solo plano para todo el campus: el plano general con la planta baja de cada bloque
-- en su posición real, los 296 espacios de todos los pisos (bloques 1, 2A, 2B, 3, 4-5, 6, 7
-- y 8) y la malla de caminos para la app. Generado desde los DWG del levantamiento
-- arquitectónico (febrero de 2019).
--
-- Requiere V2 y V3. Se puede ejecutar varias veces:
--   psql -U postgres -d ucc_orientacion -1 -f db/datos_mapa_campus.sql
--
-- Reemplaza la versión anterior de 18 planos por piso: mueve sus espacios a este plano y
-- borra esos planos. Los planos que haya creado el administrador no se tocan.
-- Los espacios de servicio (aseos, bodegas, cuartos técnicos, lockers) quedan inactivos.
-- ============================================================

SET client_min_messages = warning;

-- Versión anterior (solo Bloque 2): la Oficina 22 cambió de código OF-22 a OF-2-22.
UPDATE espacio SET codigo = 'OF-2-22' WHERE id = '5f100b4a-a842-5db7-8230-eb63e72a7bc4' AND codigo = 'OF-22'
  AND NOT EXISTS (SELECT 1 FROM espacio WHERE codigo = 'OF-2-22');

